-- e7-0025-0026-sqleditor-apply-v1.sql — ONE atomic DO statement for the Supabase SQL editor (schema owner = dashboard `postgres`). C116.
-- Reviewable packet for the maraVilla shared DEV TEST database at EXACTLY 0001-0024. ROOT reviews and owns any actual shared apply; this file is not an
-- owner command. LABELLED SPECIALISATION of the accepted claude/e7-0024-sqleditor-apply-v1.sql for TWO consecutive migrations: applies EXACTLY
-- db/migrations/0025_gn_sink_recipient_scope.up.sql then 0026_pipeline_kickoff_source_rebind.up.sql (bytes embedded verbatim, each sha256-checked in-transaction) mirroring
-- db/lib/migrate.js migrateUp: advisory xact lock 7302215001; TEST instance + schema-owner role; history exactly 0001-0024 (names + checksums = the
-- accepted 0024 packet's POST aggregate); FULL PRE schema identity + the 0024 kickoff catalog for the runtime app role; quiescence (hosted-run lock,
-- work / intent / operation leases, in-flight operations, prepared transactions, other sessions' write locks on booking relations); then 0025 up + ONE
-- tracking row, the FULL MID identity, 0026 up + ONE tracking row, the FULL POST identity, the merged hosted kickoff runner's CATALOG_PINS for the
-- runtime app role (main adacbdad: claim src fb103173), the claim's expected_source_digest literal 880db5b3 (and no f09bcbbd), the sink predicate
-- (delivered@resend.dev in scope, a look-alike out, the .invalid scope unchanged), unchanged 0001-0024 history rows (whole rows), EVERY booking table's
-- count + whole-row fingerprint (incl. pipeline_kickoff_requests and the notification tables; 0025 / 0026 add or drop no table or column), the intent id
-- set and the sanitized protected-reservation / historical-intent fingerprints.
-- Any drift → RAISE → the whole statement rolls back (schema, data and history unchanged). Never adopts, upserts, backfills, repairs, widens a grant or
-- runs a down; never embeds 0001-0024. Zero booking DML. Returns no guest field and no credential.
-- REPLAY: on a database already at EXACTLY the pinned POST state (history 0001-0026 aggregate + full POST identity + kickoff catalog) it is a provable
-- NO-OP (no write, notice E7_2526_ALREADY_EXACT_NOOP). Any other state at or above 25 (incl. a 0025-only state) → E7_2526_POST_STATE_MISMATCH_STOP;
-- never "repaired" or continued by this packet. After an UNCERTAIN issuance ROOT runs claude/e7-0025-0026-readback-v1.sql FIRST and never re-issues blindly.
-- Applying 0025 + 0026 enables NO send and NO dispatch: every hosted runner on main ships executeEnabled / dispatchEnabled FALSE; no worker, flag,
-- variable or workflow changes. Admission of the sink address is NOT a send permission; provider acceptance at the sink is NOT inbox delivery.
-- Generated by claude/gen-0025-0026-wrapper.py from the merged migration bytes + claude/e7-0025-0026-pins-v1.json (disposable-cluster derived); the
-- identity probe is claude/e7-0025-0026-inventory.sql verbatim. TIME BOUND: the SET LOCAL statements below run BEFORE the DO in the same editor batch
-- (one implicit transaction block), so they bound the DO and leave the caller's session settings unchanged afterwards.
SET LOCAL statement_timeout = '180s';
SET LOCAL lock_timeout = '5s';
DO $e7pkg$
DECLARE
  up25      constant text  := $e7_0025_up$-- 0025_gn_sink_recipient_scope (up) — Stage E7 C116: admit EXACTLY ONE simulation-sink RECIPIENT beside the v1 `.invalid` scope.
-- Base: schema 24 (0024 applied). DISPOSABLE LOCAL test databases by this task; any shared DEV apply is a separate, reviewed packet.
--
--   * booking.gn_recipient_in_scope(text) is replaced IN PLACE (CREATE OR REPLACE): same name / signature / return type, same LANGUAGE sql,
--     IMMUTABLE, SECURITY INVOKER and SET search_path = pg_catalog, booking. CREATE OR REPLACE keeps the function's OID, OWNER and ACL (the 0016
--     REVOKE ALL … FROM PUBLIC stays in force; NO grant is added). Its two callers (guest_notification_class, guest_notification_refusal) are
--     unchanged and pick the new predicate up by name.
--   * New predicate = the unchanged v1 test (length ≤ 254 AND the exact `.invalid` regex) OR exact equality with 'delivered@resend.dev' (Resend's
--     documented delivery-SIMULATION address). Exact text equality: no lower(), trim, +label, subdomain, trailing dot or look-alike; NULL → false.
--     It mirrors lib/checkout/isRecipientInScope (JS) — the parity is tested on PostgreSQL 16 and 17.
--   * RECIPIENT scope only: no sender rule exists in SQL and none is added; the JS sender checks and the gn-v1 builder are unchanged, so the v1
--     (mock) path still refuses the sink before any claim. No table, row, claim, latch, render, receipt, lifecycle or grant is touched.
--   * HONEST LABEL: admission to the scope is NOT a send permission (the hosted runner, its gates and executeEnabled decide) and provider
--     acceptance at the sink is NOT delivery to any real inbox.
CREATE OR REPLACE FUNCTION booking.gn_recipient_in_scope(p_email text) RETURNS boolean
LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path = pg_catalog, booking AS $$
  SELECT coalesce(length(p_email) <= 254 AND (p_email ~ '^[a-z0-9._+-]{1,64}@([a-z0-9-]{1,63}\.)+invalid$' OR p_email = 'delivered@resend.dev'), false)
$$;
$e7_0025_up$;
  up26      constant text  := $e7_0026_up$-- 0026_pipeline_kickoff_source_rebind (up) — Stage E7 C116: rebind ONLY the reviewed ENABLE source-digest LITERAL in booking.claim_pipeline_kickoff.
-- Base: schema 25 (0025 applied). DISPOSABLE LOCAL test databases by this task; any shared DEV apply is a separate, reviewed packet.
--
--   * The pipeline ENABLE source frame moved f09bcbbd… → 880db5b3… because main's pipeline workflow test no longer pins the C50 notification
--     runner (moved to a cross-runner regression outside every runtime frame; breaks the C116 cycle). The runner / workflow bytes are unchanged.
--   * CREATE OR REPLACE of the SAME function: same signature / return type / LANGUAGE plpgsql / VOLATILE / SECURITY DEFINER / SET search_path =
--     pg_catalog, booking; the OID, OWNER and ACL are kept (the 0024 REVOKE ALL … FROM PUBLIC and the ONE GRANT EXECUTE TO mv_booking_app stay; no
--     grant is added). The body is BYTE-IDENTICAL to 0024 except the one expected_source_digest literal; every claim condition, lock order, refusal
--     code and the closure-digest literal f7d7cad6… are unchanged. No table, row, trigger, policy or other function is touched.
--   * The down migration restores the exact 0024 body (literal f09bcbbd…).
CREATE OR REPLACE FUNCTION booking.claim_pipeline_kickoff(p_intent uuid, p_worker text, p_plan_hash text, p_inputs jsonb) RETURNS text
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, booking AS $$
DECLARE i booking.intents%ROWTYPE; r booking.pipeline_kickoff_requests%ROWTYPE; v_why text; v_expected jsonb;
BEGIN
  IF p_intent IS NULL OR p_worker IS NULL OR p_worker !~ '^[A-Za-z0-9._:-]{1,100}$' OR p_plan_hash IS NULL OR p_plan_hash !~ '^[0-9a-f]{64}$'
     OR p_inputs IS NULL OR jsonb_typeof(p_inputs) <> 'object' THEN
    RAISE EXCEPTION 'KICKOFF_ARGUMENT_INVALID' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT * INTO i FROM booking.intents WHERE id = p_intent FOR SHARE;                -- lock order: intent, then request (as applyEvent → trigger)
  SELECT * INTO r FROM booking.pipeline_kickoff_requests WHERE intent_id = p_intent FOR UPDATE;
  IF NOT FOUND THEN RETURN 'NO_REQUEST'; END IF;
  IF r.state <> 'requested' THEN RETURN 'NOT_REQUESTED:' || upper(r.state); END IF;
  v_why := CASE WHEN i.id IS NULL THEN 'INTENT_NOT_FOUND' ELSE booking.pipeline_kickoff_refusal(i, r) END;
  IF v_why IS NULL THEN
    v_expected := jsonb_build_object(
      'mode', 'execute', 'approval_ref', 'E7-KICKOFF-' || r.ref || '-v' || r.authorized_version, 'intent_id', r.intent_id::text, 'booking_ref', r.ref,
      'expected_version', r.authorized_version::text,
      'not_before', to_char(date_trunc('milliseconds', r.intent_created_at) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
      'payment_intent_id', r.payment_intent_id, 'amount_minor', r.amount_minor::text, 'currency', 'USD', 'expected_plan_hash', p_plan_hash,
      -- C108-F2: the reviewed ENABLE revision's source / closure digests are LITERAL here (never copied from the caller)
      'expected_source_digest', '880db5b33024edbf0879fbaf5a3826e3622db12fd1808e8c2047238da507fe1b',
      'expected_closure_digest', 'f7d7cad646eaed2fb37a63e031157732ee6e2a44824f9d935d6b9104e08f7273');
    IF p_inputs IS DISTINCT FROM v_expected THEN
      v_why := 'INPUTS_NOT_BOUND';
    END IF;
  END IF;
  IF v_why IS NOT NULL THEN
    UPDATE booking.pipeline_kickoff_requests SET state = 'refused', settled_at = clock_timestamp(), outcome_code = v_why WHERE intent_id = p_intent;
    RETURN 'REFUSED:' || v_why;
  END IF;
  UPDATE booking.pipeline_kickoff_requests SET state = 'claimed', claim_worker = p_worker, claimed_at = clock_timestamp(), plan_hash = p_plan_hash,
    dispatch_inputs = p_inputs WHERE intent_id = p_intent;
  RETURN 'CLAIMED';
END $$;
